"""Read bounded, exact-title sections of the skill's UTF-8 Markdown references."""

import argparse
import hashlib
import json
from pathlib import Path
import re
import sys


class ReaderError(Exception):
    def __init__(self, code, message):
        self.code = code
        super().__init__(message)


class Parser(argparse.ArgumentParser):
    def error(self, message):
        raise ReaderError("invalid_arguments", message)


class SingleHeading(argparse.Action):
    def __call__(self, parser, namespace, values, option_string=None):
        if getattr(namespace, self.dest, None) is not None:
            raise ReaderError("invalid_arguments", "Use one --heading per invocation; repeated --heading is not supported.")
        setattr(namespace, self.dest, values)


def headings(text):
    """Recognize ATX headings outside fenced and indented code."""
    found = []
    fence = None
    position = 0
    lines = text.splitlines(keepends=True)
    for number, line in enumerate(lines, 1):
        raw = line.rstrip("\r\n")
        if fence:
            char, length = fence
            if re.fullmatch(r" {0,3}" + re.escape(char) + "{" + str(length) + r",}[ \t]*", raw):
                fence = None
        elif not raw.startswith("\t") and not raw.startswith("    "):
            opening = re.match(r"^ {0,3}(`{3,}|~{3,})(.*)$", raw)
            if opening and (opening[1][0] != "`" or "`" not in opening[2]):
                fence = (opening[1][0], len(opening[1]))
            else:
                match = re.match(r"^ {0,3}(#{1,6})(?:[ \t]+(.*)|$)", raw)
                if match:
                    title = (match[2] or "").strip(" \t")
                    title = re.sub(r"(?:^|[ \t]+)#+[ \t]*$", "", title).rstrip(" \t")
                    found.append({"heading": title, "level": len(match[1]),
                                  "start_line": number, "start": position})
        position += len(line)
    for index, item in enumerate(found):
        boundary = next((other for other in found[index + 1:]
                         if other["level"] <= item["level"]), None)
        item["end"] = boundary["start"] if boundary else len(text)
        item["end_line"] = boundary["start_line"] - 1 if boundary else len(lines)
    return found


def run(argv=None):
    parser = Parser(description=__doc__)
    parser.add_argument("file", type=Path)
    mode = parser.add_mutually_exclusive_group(required=True)
    mode.add_argument("--heading", action=SingleHeading)
    mode.add_argument("--list", action="store_true")
    parser.add_argument("--occurrence", type=int)
    parser.add_argument("--offset", type=int, default=0)
    parser.add_argument("--max-chars", type=int, default=6000)
    parser.add_argument("--expect-sha256")
    args = parser.parse_args(argv)
    if args.offset < 0 or args.max_chars <= 0 or (args.occurrence is not None and args.occurrence <= 0):
        raise ReaderError("invalid_arguments", "Offset must be nonnegative; limits and occurrence must be positive.")
    if args.list and (args.occurrence is not None or args.offset != 0):
        raise ReaderError("invalid_arguments", "Occurrence and offset require --heading.")
    try:
        path = args.file.resolve()
        data = path.read_bytes()
        text = data.decode("utf-8")
    except UnicodeDecodeError as error:
        raise ReaderError("invalid_utf8", str(error)) from error
    except (OSError, ValueError) as error:
        raise ReaderError("source_error", str(error)) from error
    digest = hashlib.sha256(data).hexdigest()
    if args.expect_sha256 is not None and args.expect_sha256.lower() != digest:
        raise ReaderError("source_changed", "Source SHA256 does not match --expect-sha256.")
    entries = headings(text)
    result = {"source_path": str(path), "source_sha256": digest}
    if args.list:
        result["headings"] = [{key: value for key, value in entry.items()
                               if key not in ("start", "end")} for entry in entries]
        result["end_marker"] = "END_HEADING_LIST"
        return result
    matches = [entry for entry in entries if entry["heading"] == args.heading]
    if not matches:
        raise ReaderError("heading_missing", "No heading with the exact requested title.")
    if len(matches) > 1 and args.occurrence is None:
        raise ReaderError("heading_ambiguous", f"Found {len(matches)} matching headings; select --occurrence (1-based).")
    occurrence = args.occurrence or 1
    if occurrence > len(matches):
        raise ReaderError("occurrence_missing", "Requested occurrence exceeds the number of matching headings.")
    entry = matches[occurrence - 1]
    section = text[entry["start"]:entry["end"]]
    if args.offset > len(section):
        raise ReaderError("invalid_offset", "Offset exceeds the section character count.")
    end = min(len(section), args.offset + args.max_chars)
    final = end == len(section)
    result.update({key: entry[key] for key in ("heading", "level", "start_line", "end_line")})
    result.update(occurrence=occurrence, text=section[args.offset:end],
                  total_section_chars=len(section), offset=args.offset,
                  next_offset=None if final else end,
                  whole_section=args.offset == 0 and final, final_chunk=final,
                  end_marker="END_SECTION" if final else "MORE_SECTION_CONTENT")
    return result


def main():
    for stream in (sys.stdout, sys.stderr):
        if hasattr(stream, "reconfigure"):
            stream.reconfigure(encoding="utf-8", errors="backslashreplace")
    try:
        print(json.dumps(run(), ensure_ascii=False))
        return 0
    except ReaderError as error:
        print(json.dumps({"error": {"code": error.code, "message": str(error)}}, ensure_ascii=False), file=sys.stderr)
        return 2


if __name__ == "__main__":
    sys.exit(main())
